INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(51852507, 'Rose Archer', '蔷薇之圣弓手', '薔薇の聖弓手', 'Effect Monster', 'Warrior', 'EARTH', 3, 1000, 100, '自己场上有植物族怪兽存在，对方把陷阱卡发动时，把这张卡从手卡送去墓地才能发动。那个发动无效并破坏。这个效果在对方回合也能发动。'),
(80196387, 'Rose Bell of Revelation', '天启之蔷薇钟', '天啓の薔薇の鐘', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1只攻击力2400以上的植物族怪兽加入手卡。 ②：把墓地的这张卡除外才能发动。从手卡把1只攻击力2400以上的植物族怪兽特殊召唤。'),
(25090294, 'Rose Bud', '花瓣', 'ブルーメンブラット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只「元素英雄 小花蕾」作为祭品发动。从自己的手卡·卡组特殊召唤1只「元素英雄 鲜花女郎」。'),
(44125452, 'Rose Fairy', '蔷薇之妖精', '薔薇の妖精', 'Effect Monster', 'Plant', 'WIND', 3, 600, 1200, '这张卡被魔法·陷阱·效果怪兽的效果从自己卡组加入手卡的场合，这张卡可以在自己场上特殊召唤。'),
(29177818, 'Rose Girl', '玫瑰少女', 'バラガール', 'Tuner Monster', 'Plant', 'EARTH', 3, 800, 600, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上的表侧表示的植物族怪兽被送去墓地的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡在墓地存在，场上有植物族怪兽存在的场合才能发动。这张卡加入手卡。'),
(89252157, 'Rose Lover', '蔷薇恋人', '薔薇恋人', 'Effect Monster', 'Plant', 'EARTH', 1, 800, 800, '这个卡名的效果1回合只能使用1次。 ①：把墓地的这张卡除外才能发动。从手卡把1只植物族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不受对方的陷阱卡的效果影响。'),
(96385345, 'Rose Paladin', '蔷薇之圣骑士', '薔薇の聖騎士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 200, '「蔷薇之圣骑士」的②的效果1回合只能使用1次。 ①：这张卡战斗破坏对方怪兽送去墓地时，把这张卡解放才能发动。从手卡·卡组把1只植物族怪兽守备表示特殊召唤。 ②：把这张卡从手卡送去墓地才能发动。从卡组把1只7星以上的植物族怪兽加入手卡。'),
(8910240, 'Rose Papillon', '蔷薇蝴蝶', 'ローズ・パピヨン', 'Effect Monster', 'Insect', 'WIND', 3, 1400, 800, '①：只要这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只7星以上的怪兽表侧攻击表示上级召唤。 ②：只要自己场上有这张卡以外的昆虫族怪兽存在，这张卡可以直接攻击。'),
(58062306, 'Rose Princess', '蔷薇公主', 'ローズ・プリンセス', 'Effect Monster', 'Plant', 'EARTH', 3, 1200, 800, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤的这张卡当作调整使用。 ②：把这张卡从手卡丢弃才能发动。从卡组把1张「白蔷薇回廊」加入手卡。'),
(2752099, 'Rose Shaman', '蔷薇占术师', '薔薇占術師', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 200, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡解放才能发动。自己从卡组抽1张。 ②：把墓地的这张卡除外，以自己墓地1只植物族怪兽为对象才能发动。那只怪兽加入手卡。这个效果把原本等级是7星以上的植物族怪兽加入手卡的场合，可以再从卡组把1只植物族怪兽送去墓地。'),
(32485271, 'Rose Spectre of Dunn', '栖身蔷薇的恶灵', 'バラに棲む悪霊', 'Fusion Monster', 'Plant', 'DARK', 6, 2000, 1800, '「小精怪」＋「蛇椰树」'),
(41160533, 'Rose Tentacles', '蔷薇藤蔓', 'ローズ・テンタクルス', 'Effect Monster', 'Plant', 'EARTH', 6, 2200, 1200, '这张卡不能特殊召唤。自己的战斗阶段开始时对方场上有表侧表示植物族怪兽存在的场合，这个回合这张卡可以在通常攻击外加上那些植物族怪兽数量的攻击。这张卡战斗破坏植物族怪兽的场合，给与对方基本分300分伤害。'),
(71645243, 'Rose Token', '黑花园', 'ブラック・ガーデン', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(23087070, 'Rose Witch', '蔷薇之魔女', 'ローズ・ウィッチ', 'Effect Monster', 'Plant', 'EARTH', 4, 1600, 1000, '植物族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。'),
(1557341, 'Rose, Warrior of Revenge', '复仇的女战士 罗丝', '復讐の女戦士ローズ', 'Tuner Monster', 'Warrior', 'FIRE', 4, 1600, 600, '①：这张卡给与对方战斗伤害的场合发动。给与对方300伤害。'),
(46303688, 'Roulette Barrel', '轮盘炸弹', 'ルーレットボマー', 'Effect Monster', 'Machine', 'LIGHT', 4, 1000, 2000, '在自己的每回合的主要阶段可以掷2次骰子，在掷出的点数中选择1个，破坏场上1只表侧表示的与此点数相同等级的怪兽。'),
(36708764, 'Roulette Spider', '轮盘蜘蛛', 'ルーレット・スパイダー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时才能发动。掷1次骰子，出现数目的效果适用。 1·自己基本分变成一半。 2·那次攻击变成对自己的直接攻击。 3·选自己场上1只怪兽，攻击对象转移为那只怪兽进行伤害计算。 4·选攻击怪兽以外的对方场上1只怪兽，攻击对象转移为那只怪兽进行伤害计算。 5·那次攻击无效，给与对方那只怪兽的攻击力数值的伤害。 6·那只对方怪兽破坏。'),
(93708824, 'Roxrose Dragon', '十六夜蔷薇龙', 'ロクスローズ・ドラゴン', 'Tuner Monster', 'Dragon', 'DARK', 3, 1600, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。把「十六夜蔷薇龙」以外的有「黑蔷薇龙」的卡名记述的1张卡从卡组加入手卡。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的「蔷薇龙」怪兽或植物族同调怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡加入手卡。'),
(58769832, 'Royal Archfiend', '皇室恶魔', 'ロワイヤル・デーモン', 'Effect Monster', 'Fiend', 'FIRE', 7, 2400, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡·场上的这张卡解放才能发动。从卡组把「王家恶魔」以外的1张「恶魔」卡加入手卡。这个回合，自己不是「恶魔」怪兽不能从额外卡组特殊召唤，在通常召唤外加上只有1次，自己主要阶段可以把1只恶魔族怪兽召唤。 ②：这张卡在墓地存在的状态，自己的仪式怪兽被战斗破坏时才能发动。这张卡特殊召唤。'),
(33950246, 'Royal Command', '王宫的号令', '王宮の号令', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '全部的反转效果的怪兽的发动和效果无效化。'),
(51452091, 'Royal Decree', '王宫的通告', '王宮のお触れ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，场上的其他的陷阱卡的效果无效化。'),
(54040221, 'Royal Firestorm Guards', '炎帝近卫兵', '炎帝近衛兵', 'Effect Monster', 'Pyro', 'FIRE', 4, 1700, 1200, '①：这张卡召唤的场合，以自己墓地4只炎族怪兽为对象发动。那4只怪兽回到卡组。那之后，自己抽2张。'),
(300101004, 'Royal Flush', NULL, NULL, 'Skill Card', 'Yugi', NULL, NULL, NULL, NULL, NULL),
(39239728, 'Royal Guard', '王家守卫', 'ロイヤルガード', 'Normal Monster', 'Machine', 'EARTH', 6, 1900, 2200, '为了守护王座而开发的，且拥有意志的机械部队。'),
(16509093, 'Royal Keeper', '王族亲卫队', '王族親衛隊', 'Effect Monster', 'Zombie', 'EARTH', 4, 1600, 1700, '这张卡1个回合可以有1次变回里侧守备表示。这张卡反转时，在回合结束前这张卡的攻击力守备力上升300。'),
(68280530, 'Royal Knight', '王家骑士', 'ロイヤルナイツ', 'Effect Monster', 'Fairy', 'LIGHT', 3, 1300, 800, '这张卡战斗破坏怪兽送去墓地时，自己基本分回复破坏怪兽的守备力的数值。'),
(66661678, 'Royal Knight of the Ice Barrier', '冰结界的皇家骑士', '氷結界のロイヤル・ナイト', 'Effect Monster', 'Warrior', 'WATER', 5, 2000, 2000, '①：这张卡上级召唤的场合发动。在对方场上把1只「冰棺衍生物」（水族·水·1星·攻1000/守0）攻击表示特殊召唤。这衍生物不能为上级召唤而解放。'),
(70791313, 'Royal Magical Library', '王立魔法图书馆', '王立魔法図書館', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, NULL, 2000, '①：只要这张卡在怪兽区域存在，每次自己或者对方把魔法卡发动，给这张卡放置1个魔力指示物（最多3个）。 ②：把这张卡3个魔力指示物取除才能发动。自己从卡组抽1张。'),
(93016201, 'Royal Oppression', '王宫的弹压', '王宮の弾圧', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '可以支付800基本分，怪兽的特殊召唤以及包含怪兽的特殊召唤的效果无效并破坏。这个效果对方玩家也能使用。'),
(80893872, 'Royal Penguins Garden', '皇家企鹅花园', 'ロイヤル・ペンギンズ・ガーデン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把「王家企鹅花园」以外的1张「企鹅」卡加入手卡。 ②：1回合1次，自己主要阶段才能发动。从手卡以及自己场上的表侧表示怪兽之中选1只「企鹅」怪兽，那只怪兽的等级直到回合结束时下降1星。那之后，选自己1张手卡丢弃。'),
(26586849, 'Royal Prison', '王宫的牢狱', '王宮の牢獄', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，双方玩家不能把墓地的怪兽特殊召唤。'),
(74289646, 'Royal Rhino with Deceitful Dice', '立骰犀王', '犀子の王様', 'Effect Monster', 'Beast', 'EARTH', 1, 600, 600, '①：1回合1次，卡的效果发动时才能发动（伤害步骤也能发动）。掷1次骰子。这个效果的发动时积累的连锁数量的以下效果适用。 ●2个：这张卡的攻击力直到回合结束时上升出现的数目×500。 ●3个：给与对方为出现的数目×500伤害。 ●4个以上：把最多有出现的数目数量的场上的卡破坏。'),
(58415502, 'Royal Straight', '同花大顺', 'ロイヤル・ストレート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从手卡以及自己场上的表侧表示怪兽之中选「王后骑士」「卫兵骑士」「国王骑士」各1只送去墓地。那之后，从自己的手卡·卡组·额外卡组·墓地选有「王后骑士」「卫兵骑士」「国王骑士」的卡名全部记述的1只怪兽特殊召唤。'),
(11020863, 'Royal Straight Slasher', '同花大顺剑士', 'ロイヤル・ストレート・スラッシャー', 'Effect Monster', 'Warrior', 'LIGHT', 6, 2400, 1350, '这张卡不能通常召唤，用「同花大顺」的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：自己墓地有「王后骑士」「卫兵骑士」「国王骑士」全部存在的场合才能发动。1～5星的怪兽各1只从手卡·卡组送去墓地，对方场上的卡全部破坏。 ②：这张卡被战斗破坏时，以自己墓地最多3只战士族·光属性怪兽为对象才能发动。那些怪兽特殊召唤。'),
(56058888, 'Royal Surrender', '王宫的陷落', '王宮の陥落', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '对方发动永续陷阱卡时才能发动。那张卡的发动和效果无效，并且破坏。'),
(37953640, 'Royal Swamp Eel', '龙宫的白鳝', '竜宮の白タウナギ', 'Tuner Monster', 'Fish', 'WATER', 4, 1700, 1200, '把这张卡作为同调素材的场合，其他的同调素材怪兽必须全部是鱼族怪兽。'),
(72405967, 'Royal Tribute', '王家的牲祭', '王家の生け贄', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '当自己场上有「王家长眠之谷」存在时才能发动。双方玩家把手卡中的怪兽卡全部丢弃去墓地。'),
(86742443, 'Royal Writ of Taxation', '王宫的重税', '王宮の重税', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方回合的准备阶段时才能发动。随机选择对方的1张手卡并确认。选择的卡或者同名卡直到下次自己的结束阶段结束时没有召唤或者发动的场合，给与对方基本分1000分伤害。有召唤或者发动的场合，自己受到1000分伤害。'),
(734741, 'Rubic, Malebranche of the Burning Abyss', '彼岸恶鬼 路比冈德', '彼岸の悪鬼 ラビキャント', 'Tuner Monster', 'Fiend', 'DARK', 3, 100, 2100, '「彼岸的恶鬼 鲁比坎泰」的①的效果1回合只能使用1次。把这张卡作为同调素材的场合，不是「彼岸」怪兽的同调召唤不能使用。 ①：自己场上没有魔法·陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己场上有「彼岸」怪兽以外的怪兽存在的场合这张卡破坏。'),
(6906306, 'Rubysapphirus, the Adamant Jewel', '至刚之玉 鲁碧萨绯尔斯', '至鋼の玉 ルーベサフィルス', 'XYZ Monster', 'Rock', 'EARTH', 9, 2700, 1600, '9星怪兽×2只以上 ①：这张卡得到这张卡作为超量素材中的怪兽属性的以下效果。 ●炎：这张卡向持有比这张卡高的攻击力的怪兽攻击的攻击宣言时才能发动。这张卡的攻击力直到那次伤害步骤结束时变成2倍。 ●水：对方回合1次，以自己场上1张卡为对象才能发动。这个回合，那张卡为对象由对方发动的效果无效化。 ②：这张卡被破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(24779554, 'Rucia of the White Forest', '白森的露西亚', '白き森のルシア', 'Tuner Monster', 'Spellcaster', 'LIGHT', 4, 800, 1500, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上有「白森林」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：从自己的手卡·场上把1张魔法·陷阱卡送去墓地才能发动。自己抽1张。 ③：自己·对方回合，这张卡在墓地存在的场合，以自己的场上·墓地1只「白森林」同调怪兽为对象才能发动。那只怪兽回到额外卡组，这张卡效果无效特殊召唤。'),
(40139997, 'Ruddy Rose Dragon', '红莲蔷薇龙', 'ブラッド・ローズ・ドラゴン', 'Synchro Monster', 'Dragon', 'FIRE', 10, 3200, 2400, '调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤的场合才能发动。双方墓地的卡全部除外。这张卡用「黑蔷薇龙」或植物族同调怪兽为素材作同调召唤的场合，可以再把场上的其他卡全部破坏。 ②：要让卡破坏的效果由对方发动时，把这张卡解放才能发动。那个发动无效。那之后，可以从自己的额外卡组·墓地把1只「黑蔷薇龙」特殊召唤。'),
(29107423, 'Ruddy Rose Witch', '红莲蔷薇之魔女', '紅蓮薔薇の魔女', 'Tuner Monster', 'Plant', 'LIGHT', 1, 800, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。从卡组把1只「黑蔷薇之魔女」加入手卡，从卡组选1只3星以下的植物族怪兽在卡组最上面放置。那之后，可以从手卡把1只「黑蔷薇之魔女」召唤。 ②：把墓地的这张卡除外才能发动。从自己墓地的怪兽或者除外的自己怪兽之中选1只「黑蔷薇龙」或者「红莲蔷薇龙」回到额外卡组。'),
(26378150, 'Rude Kaiser', '粗暴帝王', 'ルード・カイザー', 'Normal Monster', 'Beast-Warrior', 'EARTH', 5, 1800, 1600, '双手持有的魔人之斧的破坏力相当强大！'),
(24919805, 'Ruffian Railcar', '无赖特急 战斗列车', '無頼特急バトレイン', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，自己主要阶段才能发动。给与对方500伤害。这个效果发动的回合，自己不能进行战斗阶段。 ②：这张卡被送去墓地的回合的结束阶段才能发动。从卡组把1只机械族·地属性·10星怪兽加入手卡。'),
(50139096, 'Ruin, Angel of Oblivion', '破灭之天使 露茵', '破滅の天使ルイン', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 4, 1700, 1000, '「世界不灭」降临。 ①：这张卡的卡名只要在手卡·场上存在当作「破灭之女神 露茵」使用。 ②：这张卡仪式召唤成功的场合发动。这个回合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ③：这张卡被送去墓地的场合，以自己场上1只仪式怪兽为对象才能发动。只要那只怪兽在自己场上表侧表示存在，在自己的仪式怪兽的攻击宣言时对方不能把卡的效果发动。'),
(46427957, 'Ruin, Queen of Oblivion', '破灭之女神 露茵', '破滅の女神ルイン', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 8, 2300, 2000, '「世界末日」降临。 ①：这张卡的攻击破坏对方怪兽时才能发动。这张卡只再1次可以继续攻击。'),
(13518809, 'Ruin, Supreme Queen of Oblivion', '破灭之美神 露茵', '破滅の美神ルイン', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 10, 2900, 3000, '「世界不灭」降临 ①：这张卡的卡名只要在手卡·场上存在当作「破灭之女神 露茵」使用。 ②：只要仪式召唤的这张卡在怪兽区域存在，自己场上的仪式怪兽不会被效果破坏。 ③：只使用仪式怪兽作仪式召唤的这张卡在同1次的战斗阶段中可以作2次攻击。 ④：这张卡战斗破坏对方怪兽时才能发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(69868555, 'Ruins of the Divine Dragon Lords', '巨神龙的遗迹', '巨神竜の遺跡', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上有7·8星的龙族怪兽存在，从墓地以外有怪兽特殊召唤的场合发动。那些怪兽的效果直到回合结束时无效化。 ②：1回合1次，把这张卡以外的自己场上1张表侧表示的卡送去墓地才能发动。在自己场上把1只「巨龙衍生物」（龙族·光·1星·攻/守0）特殊召唤。 ③：这张卡在墓地存在的场合，把自己的手卡·场上1只7·8星的龙族怪兽送去墓地才能发动。这张卡加入手卡。'),
(83831356, 'Runaway Karakuri', '机巧大暴走', 'カラクリ大暴走', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择场上表侧表示存在的1只名字带有「机巧」的怪兽发动。直到结束阶段时，选择的怪兽的攻击力上升1000，效果无效化。'),
(1516510, 'Rune-Eyes Pendulum Dragon', '卢恩眼灵摆龙', 'ルーンアイズ・ペンデュラム・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 8, 3000, 2000, '「异色眼灵摆龙」＋魔法师族怪兽 ①：这张卡得到「异色眼灵摆龙」以外的作为融合素材的怪兽的原本等级的以下效果。 ●4星以下：这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。 ●5星以上：这张卡在同1次的战斗阶段中最多3次可以向怪兽攻击。 ②：场上的灵摆召唤的怪兽作为素材让这张卡融合召唤成功的回合，这张卡不受对方的效果影响。'),
(29595202, 'Runick Allure', '神碑之诱骗', '神碑の誑かし', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「神碑的欺诳」在自己场上只能有1张表侧表示存在。 ②：每次自己或者对方把速攻魔法卡发动才发动。从对方卡组上面把1张卡除外。'),
(94445733, 'Runick Destruction', '破坏之神碑', '破壊の神碑', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。 ●以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。那之后，从对方卡组上面把4张卡除外。 ●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。'),
(66712905, 'Runick Dispelling', '解咒之神碑', '解呪の神碑', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。 ●对方在抽卡阶段以外从卡组把卡加入手卡的场合才能发动。对方手卡随机选1张丢弃。那之后，从对方卡组上面把2张卡除外。 ●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。'),
(68957034, 'Runick Flashing Fire', '闪耀火焰之神碑', '輝く炎の神碑', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。 ●以特殊召唤的对方场上1只怪兽为对象才能发动。那只怪兽破坏。那之后，从对方卡组上面把2张卡除外。 ●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。'),
(92107604, 'Runick Fountain', '卢恩神碑之泉', '神碑の泉', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，自己在对方回合可以把「神碑」速攻魔法卡从手卡发动。 ②：1回合1次，自己把「神碑」速攻魔法卡发动的场合，以自己墓地最多3张「神碑」速攻魔法卡为对象才能发动。那些卡用喜欢的顺序回到卡组下面。那之后，自己从卡组抽出回去的数量。'),
(30430448, 'Runick Freezing Curses', '冰冻诅咒之神碑', '凍てつく呪いの神碑', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。 ●以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。那之后，从对方卡组上面把3张卡除外。 ●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。'),
(20618850, 'Runick Golden Droplet', '黄金露滴之神碑', '黄金の雫の神碑', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。 ●对方从卡组抽1张。那之后，从对方卡组上面把4张卡除外。 ●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。'),
(67835547, 'Runick Slumber', '微睡之神碑', 'まどろみの神碑', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。 ●以场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽只有1次不会被战斗·效果破坏，不能攻击。那之后，从对方卡组上面把3张卡除外。 ●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。'),
(93229151, 'Runick Smiting Storm', '愤怒风暴之神碑', '怒れる嵐の神碑', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。 ●把最多有对方场上的卡数量的卡从对方卡组上面除外。 ●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。'),
(31562086, 'Runick Tip', '神碑之枪尖', '神碑の穂先', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。这张卡的发动后，下次的自己战斗阶段跳过。 ●从卡组把「神碑的锋芒」以外的1张「神碑」卡加入手卡。那之后，从对方卡组上面把1张卡除外。 ●从额外卡组把1只「神碑」怪兽在额外怪兽区域特殊召唤。'),
(70046172, 'Rush Recklessly', '突进', '突進', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升700。'),
(36736723, 'Rush Warrior', '突击战士', 'ラッシュ・ウォリアー', 'Effect Monster', 'Warrior', 'WIND', 2, 300, 1200, '「突进战士」的①②的效果1回合各能使用1次。 ①：自己的「战士」同调怪兽和对方怪兽进行战斗的伤害计算时，把这张卡从手卡送去墓地才能发动。那只进行战斗的自己怪兽的攻击力只在那次伤害计算时变成2倍。 ②：把墓地的这张卡除外，以自己墓地1只「同调士」怪兽为对象才能发动。那只怪兽加入手卡。'),
(73148972, 'Ruthless Denial', '无情的抹杀', '無情の抹殺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上存在的1只怪兽发动。选择的自己怪兽送去墓地，对方手卡随机1张送去墓地。'),
(300302071, 'Ruthless Means', NULL, NULL, 'Skill Card', 'The Supreme K', NULL, NULL, NULL, NULL, NULL),
(21502796, 'Ryko, Lightsworn Hunter', '光道猎犬 莱可', 'ライトロード・ハンター ライコウ', 'Flip Effect Monster', 'Beast', 'LIGHT', 2, 200, 100, '①：这张卡反转的场合发动。可以选场上1张卡破坏。从自己卡组上面把3张卡送去墓地。'),
(83550869, 'Ryko, Twilightsworn Fighter', '暮光道斗犬 莱可', 'トワイライトロード・ファイター ライコウ', 'Effect Monster', 'Beast', 'DARK', 2, 200, 100, '①：这张卡召唤·反转的场合，从自己的手卡·墓地把1只「光道」怪兽除外才能发动。选场上1张卡除外。 ②：1回合1次，这张卡以外的自己的「光道」怪兽的效果发动的场合发动。从自己卡组上面把3张卡送去墓地。'),
(57281778, 'Ryu Kokki', '龙骨鬼', '龍骨鬼', 'Effect Monster', 'Zombie', 'DARK', 6, 2400, 2000, '和这张卡进行战斗的怪兽是战士族·魔法师族的场合，伤害步骤结束时把那只怪兽破坏。'),
(63737050, 'Ryu Okami', '龙大神', '龍大神', 'Effect Monster', 'Wyrm', 'LIGHT', 8, 2900, 1200, '①：对方对怪兽的特殊召唤成功的场合发动。对方选额外卡组1张卡送去墓地。'),
(49868263, 'Ryu Senshi', '龙战士', 'ドラゴン・ウォリアー', 'Fusion Monster', 'Warrior', 'EARTH', 6, 2000, 1200, '「战士 戴·格雷法」＋「灵魂龙」 融合召唤这只怪兽，必须用上面所写的卡融合召唤。只要这张卡在场上存在，可以支付1000分使通常陷阱的效果无效化。以这张卡为对象的魔法卡的效果无效并破坏。'),
(90664684, 'Ryu-Ge End', '龙华袭焉', '竜華襲焉', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：对方不能把自己场上的「龙华」怪兽作为效果的对象。 ②：自己的额外卡组（表侧）或场上有「龙华」灵摆怪兽存在的场合，让自己的手卡·墓地·除外状态的2只「龙华」怪兽回到卡组，以场上1只怪兽为对象才能发动。那只怪兽破坏。 ③：这张卡被破坏的场合才能发动。永续陷阱卡以外的自己的卡组·墓地·除外状态的1张「龙华」陷阱卡在自己场上盖放。'),
(82661630, 'Ryu-Ge Realm - Dino Domains', '登龙华恐巄门', '登竜華恐巄門', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「登龙华恐巃门」在自己场上只能有1张表侧表示存在。 ②：只要这张卡在魔法与陷阱区域存在，自己场上的「龙华」怪兽的攻击力上升300。 ③：自己场上的「龙华」灵摆怪兽以及10星以上而原本种族是恐龙族的怪兽得到以下效果。 ●1回合1次，比这张卡攻击力低的场上的怪兽的效果发动时，让自己场上1张表侧表示的「龙华」永续魔法卡回到卡组最下面才能发动。那个发动无效。'),
(28669235, 'Ryu-Ge Realm - Sea Spires', '登龙华海瀧门', '登竜華海瀧門', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「登龙华海泷门」在自己场上只能有1张表侧表示存在。 ②：只要这张卡在魔法与陷阱区域存在，自己的「龙华」怪兽不会被战斗破坏。 ③：自己场上的「龙华」灵摆怪兽以及10星以上而原本种族是海龙族的怪兽得到以下效果。 ●对方回合1次，让自己场上1张表侧表示的「龙华」永续魔法卡回到卡组最下面，以场上1张卡为对象才能发动。那张卡回到手卡。'),
(55154344, 'Ryu-Ge Realm - Wyrm Winds', '登龙华幻朧门', '登竜華幻朧門', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「登龙华幻胧门」在自己场上只能有1张表侧表示存在。 ②：只要这张卡在魔法与陷阱区域存在，对方回合从双方场上送去墓地的怪兽不去墓地而除外。 ③：自己场上的「龙华」灵摆怪兽以及10星以上而原本种族是幻龙族的怪兽得到以下效果。 ●对方回合1次，让自己场上1张表侧表示的「龙华」永续魔法卡回到卡组最下面，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0。'),
(29882827, 'Ryu-Ge Rising', '龙华界辟', '竜華界闢', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1只「龙华」怪兽加入手卡。那之后，可以从手卡把1只「龙华」灵摆怪兽表侧加入额外卡组。 ②：自己场上有「龙华」灵摆怪兽卡存在的场合，自己主要阶段，从自己墓地把1只「龙华」怪兽和这张卡除外才能发动。原本种族和除外的怪兽相同的1只「龙华」怪兽从卡组特殊召唤。'),
(81549048, 'Ryu-Ge Rivalry', '龙华三界流转', '竜華三界流転', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·卡组·墓地把1只「龙华」怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。 ②：把墓地的这张卡除外，以自己的场上·墓地·除外状态的1张「龙华」永续魔法卡为对象才能发动。那张卡回到卡组最下面。那之后，自己抽1张。'),
(55276522, 'Ryu-Ge War Zone', '登龙华转生纹', '登竜華転生紋', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：作为这张卡的发动时的效果处理，从卡组选恐龙族·海龙族·幻龙族怪兽各1只，那之内的1只加入手卡，另1只除外，剩余送去墓地。这个回合，自己不是龙族·恐龙族·海龙族·幻龙族怪兽不能特殊召唤。 ②：自己的额外卡组有表侧的「创星龙华-光巴」存在的场合才能发动。从自己的卡组·墓地·除外状态各把1只「龙华」怪兽特殊召唤（相同种族最多1只）。'),
(15303296, 'Ryu-Kishin', '石像魔', 'ガーゴイル', 'Normal Monster', 'Fiend', 'DARK', 3, 1000, 500, '假装是石像，从黑暗中攻击。逃跑速度也很快。'),
(42647539, 'Ryu-Kishin Clown', '石像怪道化师', 'ガーゴイルの道化師', 'Effect Monster', 'Fiend', 'DARK', 2, 800, 500, '这张卡片召唤·反转召唤·特殊召唤时可以使对方1只表侧表示的怪兽的表示形式改变。'),
(24611934, 'Ryu-Kishin Powered', '强化石像怪', 'ガーゴイル・パワード', 'Normal Monster', 'Fiend', 'DARK', 4, 1600, 1200, '得到黑暗力量而被强化的石像怪。注意钩爪！'),
(2964201, 'Ryu-Ran', '蛋龙', 'ドラゴン・エッガー', 'Normal Monster', 'Dragon', 'FIRE', 7, 2200, 2600, '被蛋壳包围的龙。如果认为只是个小鬼的话会吃苦头的哦。'),
(6798031, 'Ryzeal Cross', '雷热涡炉・交错', 'ライゼオル・クロス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己若非同名卡不在自己场上存在的怪兽则不能超量召唤。 ②：以「雷火沸动交界机」以外的自己墓地2张「雷火沸动」卡为对象才能发动。那些卡用喜欢的顺序回到卡组下面。那之后，自己抽1张。 ③：1回合1次，对方发动的怪兽的效果的处理时，自己可以把自己场上的「雷火沸动」超量怪兽1个超量素材取除。那个场合，那个效果无效化。'),
(34909328, 'Ryzeal Detonator', '雷热涡炉・绝命导爆', 'ライゼオル・デッドネーダー', 'XYZ Monster', 'Pyro', 'LIGHT', 4, 3000, 2500, '4星「雷火沸动」怪兽×2只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。把自己墓地1只怪兽作为这张卡的超量素材。 ②：对方把卡的效果发动时，把这张卡1个超量素材取除，以场上1张卡为对象才能发动。那张卡破坏。 ③：自己场上的超量怪兽被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(7511613, 'Ryzeal Duo Drive', '雷热涡炉・双驱进击', 'ライゼオル・デュオドライブ', 'XYZ Monster', 'Thunder', 'FIRE', 4, 2500, 2000, '4星怪兽×2只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。把自己墓地1只「雷火沸动」怪兽作为这张卡的超量素材。 ②：让自己场上的怪兽的攻击力上升并让对方场上的怪兽的攻击力下降这张卡的超量素材数量×100。 ③：自己主要阶段才能发动。自己场上2个超量素材取除，从卡组把2张「雷火沸动」卡加入手卡（同名卡最多1张）。'),
(53276089, 'Ryzeal Mass Driver', '雷热涡炉・质量投击炮', 'ライゼオル・マスドライバー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这个回合中，以下效果适用。那之后，可以把这张卡作为自己场上的4阶超量怪兽的超量素材。 ●自己场上的「雷火沸动」怪兽的攻击力上升1000。 ②：这张卡从场上以外送去墓地的场合，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(33787730, 'Ryzeal Plasma Hole', '雷热涡炉・空洞电冲炮', 'ライゼオル・ホールスラスター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己场上的「雷火沸动」超量怪兽数量的对方场上的表侧表示卡为对象才能发动。那些卡破坏。那之后，可以从自己墓地把1张「雷火沸动」卡作为自己场上1只4阶超量怪兽的超量素材。 ②：把墓地的这张卡除外才能发动。用包含「雷火沸动」怪兽的自己场上的怪兽为素材进行超量召唤。'),
(60394026, 'Ryzeal Plugin', '雷热涡炉・嵌能', 'ライゼオル・プラグイン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己的墓地·除外状态的1只超量怪兽或「雷火沸动」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以从卡组把1张「雷火沸动」卡作为自己场上1只4阶超量怪兽的超量素材。这个回合，自己不用4阶超量怪兽不能攻击宣言。'),
(23377425, 'S-Force Bridgehead', '超元特防队 桥头堡', 'S－Force ブリッジヘッド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「治安战警队」怪兽加入手卡。 ②：对方怪兽向相同纵列的自己的「治安战警队」怪兽攻击宣言时才能发动。那只自己怪兽不会被那次战斗破坏。'),
(55049722, 'S-Force Chase', '超元特防队 追缉', 'S－Force チェイス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以最多有自己场上的「治安战警队」怪兽种类数量的对方场上的表侧表示的卡为对象才能发动。那些卡回到持有者手卡。 ②：自己场上的「治安战警队」怪兽为让效果发动而把手卡除外的场合，可以作为代替把墓地的这张卡除外。'),
(65479980, 'S-Force Dog Tag', '超元特防队 双狗牌', 'S－Force ドッグ・タッグ', 'Effect Monster', 'Machine', 'LIGHT', 5, 1600, 2100, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有「治安战警队」怪兽存在，对方对怪兽的召唤·特殊召唤成功的场合才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，自己主要阶段中，自己的「治安战警队」怪兽的正对面的对方怪兽不能把效果发动。'),
(91864689, 'S-Force Edge Razor', '超元特防队 刃锋', 'S－Force エッジ・レイザー', 'Effect Monster', 'Cyberse', 'DARK', 4, 1500, 1300, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡把「治安战警队 拔刃者」以外的1只「治安战警队」怪兽攻击表示特殊召唤。 ②：只要这张卡在怪兽区域存在，自己的「治安战警队」怪兽的正对面的对方怪兽不能作为连接3以上的怪兽的连接素材。'),
(21368442, 'S-Force Gravitino', '超元特防队 重力微子侠', 'S－Force グラビティーノ', 'Effect Monster', 'Psychic', 'LIGHT', 5, 2000, 1400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「治安战警队 引力微子」以外的1张「治安战警队」卡加入手卡。 ②：只要这张卡在怪兽区域存在，自己的「治安战警队」怪兽的正对面的对方怪兽从场上离开的场合除外。'),
(35334193, 'S-Force Justify', '超元特防队 证义', 'S－Force ジャスティファイ', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 2600, NULL, '包含「治安战警队」怪兽的效果怪兽3只 自己不能在这张卡所连接区让怪兽出现。这个卡名的①的效果1回合只能使用1次。 ①：自己·对方回合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。那之后，可以让那只对方怪兽向作为这张卡所连接区的对方的怪兽区域移动。 ②：这张卡攻击的伤害步骤开始时才能发动。这张卡所连接区的怪兽全部除外。'),
(27383719, 'S-Force Lapcewell', '超元特防队 拉普斯韦', 'S－Force ラプスウェル', 'Effect Monster', 'Fiend', 'LIGHT', 6, 2400, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，以「治安战警队 拉普斯韦妖」以外的自己墓地1只「治安战警队」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：从手卡把1张「治安战警队」卡除外才能发动。自己的「治安战警队」怪兽的正对面的对方怪兽全部破坏。'),
(20515672, 'S-Force Nightchaser', '超元特防队 暗夜追缉者', 'S－Force ナイトチェイサー', 'Link Monster', 'Cyberse', 'DARK', NULL, 800, NULL, '连接怪兽以外的「治安战警队」怪兽1只 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己的「治安战警队」怪兽的正对面的对方怪兽不能选择和自身相同纵列的怪兽作为攻击对象。 ②：自己·对方的主要阶段，以自己场上1只「治安战警队」怪兽为对象才能发动。那只怪兽回到持有者卡组。那之后，可以选除外的1只自己的「治安战警队」怪兽特殊召唤。'),
(95974848, 'S-Force Orrafist', '超元特防队 时缝保安官', 'S－Force オリフィス', 'Effect Monster', 'Cyberse', 'LIGHT', 4, 1800, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己的「治安战警队」怪兽的正对面的对方怪兽不会成为对方的效果的对象。 ②：对方场上的怪兽把效果发动时，从手卡把1张「治安战警队」卡除外才能发动。那只怪兽破坏。'),
(58363151, 'S-Force Pla-Tina', '超元特防队 白金蒂娜', 'S－Force プラ＝ティナ', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2200, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以「治安战警队 铂金女」以外的除外的1只自己的「治安战警队」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，自己的「治安战警队」怪兽的正对面的对方怪兽的攻击力下降600。'),
(58589739, 'S-Force Professor DiGamma', '超元特防队 迪伽玛教授', 'S－Force プロフェッサー・Ϝ', 'Effect Monster', 'Psychic', 'DARK', 3, 1000, 1500, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的表示形式变更。 ②：只要这张卡在怪兽区域存在，自己的「治安战警队」怪兽的正对面的对方怪兽不能用效果以外把表示形式变更。'),
(22180094, 'S-Force Rappa Chiyomaru', '超元特防队 乱破小夜丸', 'S－Force 乱破小夜丸', 'Effect Monster', 'Warrior', 'DARK', 2, 800, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己的「治安战警队」怪兽的正对面的对方怪兽只能选择和自身相同纵列的怪兽作为攻击对象。 ②：从手卡把1张「治安战警队」卡除外才能发动。这张卡回到持有者手卡，从卡组把「治安战警队 乱破小夜丸」以外的1只「治安战警队」怪兽守备表示特殊召唤。这个效果在对方回合也能发动。'),
(53782828, 'S-Force Retroactive', '超元特防队 追溯者', 'S－Force レトロアクティヴ', 'Effect Monster', 'Warrior', 'LIGHT', 1, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：把自己场上的怪兽作为「治安战警队」怪兽的连接素材的场合，手卡的这张卡也能作为连接素材。 ②：自己·对方的主要阶段才能发动。这张卡回到持有者手卡，从手卡把1只2星以上的「治安战警队」怪兽特殊召唤。 ③：自己场上的「治安战警队」怪兽为让效果发动而把手卡除外的场合，可以作为代替把墓地的这张卡除外。'),
(69761020, 'S-Force Showdown', '超元特防队 对决时刻', 'S－Force ショウダウン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从手卡把1只「治安战警队」怪兽守备表示特殊召唤。 ●以自己墓地1只「治安战警队」怪兽为对象才能发动。那只怪兽加入手卡。'),
(82977464, 'S-Force Specimen', '超元特防队 实验样本', 'S－Force スペシメン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：对方场上有怪兽存在的场合，从自己墓地的怪兽以及除外的自己怪兽之中以1只「治安战警队」怪兽为对象才能发动。那只怪兽在对方怪兽的正对面的自己场上特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只「治安战警队」怪兽为对象才能发动。那只自己怪兽的位置向其他的自己的主要怪兽区域移动。'),
(29301450, 'S:P Little Knight', 'S：P小夜骑士', 'S：Pリトルナイト', 'Link Monster', 'Warrior', 'DARK', NULL, 1600, NULL, '效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用融合·同调·超量·连接怪兽的其中任意种为素材作连接召唤的场合，以自己或对方的场上·墓地1张卡为对象才能发动。那张卡除外。这个回合，自己怪兽不能直接攻击。 ②：对方的效果发动时，以包含自己场上的怪兽的场上2只表侧表示怪兽为对象才能发动。那2只怪兽直到结束阶段除外。'),
(91509824, 'SA.I.dekick', '-艾-并肩伙伴', 'Ai－ボウ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上的原本攻击力是2300的电子界族怪兽数量的对方场上的表侧表示卡为对象才能发动。那些卡的效果直到回合结束时无效。 ②：把墓地的这张卡除外，以自己的除外状态的1只电子界族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(46999905, 'Saambell the Star Bonder', '绊醒师 塞姆贝尔', '絆醒師セームベル', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 3, 1400, 1300, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡已在怪兽区域存在的状态，自己场上有其他怪兽特殊召唤的场合才能发动。和这张卡相同等级的1只怪兽从手卡特殊召唤。'),
(45282603, 'Saambell the Summoner', '召唤师 塞姆贝尔', '召喚師セームベル', 'Effect Monster', 'Spellcaster', 'WIND', 2, 600, 400, '自己的主要阶段时，可以把和这张卡相同等级的1只怪兽从手卡特殊召唤。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(80831721, 'Sabatiel - The Philosopher''s Stone', '贤者之石-萨巴希尔', '賢者の石－サバティエル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地有「羽翼栗子球」怪兽存在的场合，把基本分支付一半才能发动。从卡组把1张「融合」魔法卡加入手卡。 ②：这张卡在墓地存在的场合，把自己墓地3张「贤者之石-萨巴希尔」除外，以场上1只怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升场上的攻击力最高的怪兽的攻击力数值。'),
(49645921, 'Saber Beetle', '剑角甲虫', 'セイバー・ビートル', 'Effect Monster', 'Insect', 'EARTH', 6, 2400, 600, '这张卡攻击守备表示的怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(35240714, 'Saber Combination', '军刀合击', 'セイバー・コンビネーション', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己的场上·墓地·除外状态的「X-剑士」怪兽是10只以上，自己场上的「X-剑士」怪兽的攻击力上升自身的原本守备力数值。 ②：自己从额外卡组把「X-剑士」怪兽特殊召唤的场合才能发动。从手卡·卡组把1只「X-剑士」怪兽特殊召唤。 ③：对方怪兽的攻击宣言时才能发动。从手卡把1只「X-剑士」怪兽特殊召唤。'),
(44901281, 'Saber Hole', '军刀空洞', 'セイバー・ホール', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「X-剑士」怪兽存在，自己或对方把怪兽召唤·反转召唤·特殊召唤之际才能发动。那个无效，那些怪兽破坏。'),
(35037880, 'Saber Reflection', '剑之反射', 'セイバー・リフレクト', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「剑之反射」在1回合只能发动1张。 ①：自己场上有「X-剑士」怪兽存在，自己因战斗·效果受到伤害时才能发动。自己基本分回复受到的伤害的数值，给与对方那个数值的伤害。那之后，可以从卡组把1张「剑士」魔法·陷阱卡或者1张「加特姆士」卡加入手卡。'),
(63193879, 'Saber Shark', '军刀鲨', 'セイバー・シャーク', 'Effect Monster', 'Fish', 'WATER', 4, 1600, 1200, '这张卡不能作为同调素材。自己的主要阶段时，可以选择场上1只鱼族怪兽，从以下效果选择1个发动。这个效果1回合可以使用最多2次。这个效果发动的回合，自己不能把水属性以外的怪兽特殊召唤。 ●选择的怪兽的等级上升1星。 ●选择的怪兽的等级下降1星。'),
(11052544, 'Saber Slash', '军刀斩', 'セイバー・スラッシュ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上的攻击表示的「X-剑士」怪兽数量的场上的表侧表示卡破坏。'),
(73787254, 'Saber Vault', '剑窖', 'セイバー・ヴォールト', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '场上表侧表示存在的名字带有「X-剑士」的怪兽的攻击力上升自身等级×100，守备力下降自身等级×100。'),
(37265642, 'Sabersaurus', '军刀角龙', 'セイバーザウルス', 'Normal Monster', 'Dinosaur', 'EARTH', 4, 1900, 500, '性格温顺而闻名的恐龙。据说喜欢在大草原的小巢里悠闲自在地过日子。生起气来很可怕。'),
(16261341, 'Sacred Arch-Airknight Parshath', '天空圣骑士 阿克珀耳修斯', '天空聖騎士アークパーシアス', 'Effect Monster', 'Fairy', 'LIGHT', 9, 2800, 2300, '①：这张卡在手卡·墓地存在，自己把反击陷阱卡发动的场合或者自己把怪兽的效果·魔法·陷阱卡的发动无效的场合，从自己的手卡·场上·墓地把这张卡以外的2只天使族怪兽除外才能发动。这张卡特殊召唤。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡给与对方战斗伤害时才能发动。从卡组把1张「珀耳修斯」卡或者反击陷阱卡加入手卡。'),
(30914564, 'Sacred Crane', '圣鸟仙鹤', '聖鳥クレイン', 'Effect Monster', 'Winged Beast', 'LIGHT', 4, 1600, 400, '①：这张卡特殊召唤成功的场合发动。自己从卡组抽1张。'),
(66431519, 'Sacred Fire King Garunix', '圣炎王 迦楼多尼克斯', '聖炎王 ガルドニクス', 'Effect Monster', 'Winged Beast', 'FIRE', 8, 2700, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，原本属性是炎属性的自己怪兽被战斗·效果破坏的场合才能发动。这张卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。「圣炎王 大鹏不死鸟」以外的自己的手卡·卡组·场上（表侧表示）1只兽族·兽战士族·鸟兽族的炎属性怪兽破坏。这张卡的攻击力直到回合结束时上升这个效果破坏的怪兽的攻击力一半数值。'),
(10613952, 'Sacred Noble Knight of King Artorigus', '神圣骑士王 阿托利斯', '神聖騎士王アルトリウス', 'XYZ Monster', 'Warrior', 'LIGHT', 5, 2200, 2200, '5星「圣骑士」怪兽×2 ①：这张卡超量召唤成功时，以自己墓地的「圣剑」装备魔法卡最多3种类为对象才能发动。作为对象的卡给这张卡装备。 ②：1回合1次，把这张卡1个超量素材取除，以这张卡以外的场上1只怪兽为对象才能发动。那只怪兽破坏。 ③：这张卡从场上送去墓地的场合，以自己墓地1只4星以上的「圣骑士」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(78876707, 'Sacred Noble Knight of King Custennin', '神圣骑士王 康尼厄斯', '神聖騎士王コルネウス', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 1500, 2500, '4星「圣骑士」怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡的超量素材任意数量取除，以那个数量的对方场上的卡为对象才能发动。那些卡回到持有者手卡。 ②：这张卡被战斗·效果破坏送去墓地的场合才能发动。「神圣骑士王 康尼厄斯」以外的1只「圣骑士」超量怪兽当作超量召唤从额外卡组特殊召唤，把墓地的这张卡在下面重叠作为超量素材。'),
(61441708, 'Sacred Phoenix of Nephthys', '奈芙蒂斯之凤凰神', 'ネフティスの鳳凰神', 'Effect Monster', 'Winged Beast', 'FIRE', 8, 2400, 1600, '①：这张卡被效果破坏送去墓地的场合，下次的自己准备阶段发动。这张卡从墓地特殊召唤。 ②：这张卡的①的效果特殊召唤的场合发动。场上的魔法·陷阱卡全部破坏。'),
(24793135, 'Sacred Scrolls of the Gizmek Legend', '机巧传－神使记纪图', '機巧伝－神使記紀図', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从自己卡组上面把3张卡翻开。可以从那之中选攻击力和守备力的数值相同的1只机械族怪兽加入手卡。剩下的卡里侧表示除外。 ②：每次攻击力和守备力的数值相同的机械族怪兽召唤·特殊召唤给这张卡放置1个指示物。 ③：这张卡的指示物数量是10以上的场合，攻击力和守备力的数值不同的场上的怪兽不能把效果发动。'),
(98850929, 'Sacred Serpent''s Wake', '圣蛇的息吹', '聖蛇の息吹', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上有仪式·融合·同调·超量怪兽之内2种类以上存在的场合，可以从那些怪兽种类的以下效果选1个以上发动。「圣蛇的息吹」在1回合只能发动1张。 ●2种类以上：选择自己墓地1只怪兽或者从游戏中除外的1只自己怪兽加入手卡。 ●3种类以上：选择自己墓地1张陷阱卡加入手卡。 ●4种类：选择「圣蛇的息吹」以外的自己墓地1张魔法卡加入手卡。'),
(44877690, 'Sacred Spirit of the Ice Barrier', '冰结界的神精灵', '氷結界の神精霊', 'Spirit Monster', 'Zombie', 'WATER', 4, 1600, 1200, '这张卡不能特殊召唤。 ①：这张卡召唤·反转的回合的结束阶段发动。这张卡回到手卡。自己场上有其他的「冰结界」怪兽存在的场合，作为代替把以下效果发动。 ●这张卡召唤·反转的回合的结束阶段，以对方场上1只怪兽为对象发动。那只对方怪兽回到手卡。'),
(45725480, 'Sacred Sword of Seven Stars', '七星宝刀', '七星の宝刀', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡以及自己场上的表侧表示怪兽之中把1只7星怪兽除外才能发动。自己从卡组抽2张。'),
(9349094, 'Sacred Tree Beast, Hyperyton', '神树兽 亥许利冬', '神樹獣ハイペリュトン', 'XYZ Monster', 'Plant', 'EARTH', 9, 2600, 1900, '9星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己回合，自己把魔法·陷阱·怪兽的效果发动时，以和那个效果相同种类（怪兽·魔法·陷阱）的自己墓地1张卡为对象才能发动。把作为对象的卡在这张卡下面重叠作为超量素材。 ②：对方回合，魔法·陷阱·怪兽的效果发动时才能发动。和那个效果相同种类（怪兽·魔法·陷阱）的1个超量素材从这张卡取除，那个发动无效并破坏。'),
(94185340, 'Sacrifice Level-Up', '牲祭升阶', 'サクリファイス・ランクアップ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只超量怪兽为对象才能发动。那只怪兽2个超量素材除外，比那只怪兽阶级高1阶的1只超量怪兽从额外卡组特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(65314286, 'Sadion, the Timelord', '时械神 然迪恩', '時械神サディオン', 'Effect Monster', 'Fairy', 'WIND', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时，自己基本分比4000少的场合发动。自己基本分变成4000。 ④：自己准备阶段发动。这张卡回到持有者卡组。'),
(38296564, 'Safe Zone', '安全地带', '安全地帯', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '以场上1只表侧攻击表示怪兽为对象才能把这张卡发动。 ①：只要这张卡在魔法与陷阱区域存在，那只表侧表示怪兽不会成为对方的效果的对象，不会被战斗以及对方的效果破坏，不能向对方直接攻击。这张卡从场上离开时那只怪兽破坏。那只怪兽从场上离开时这张卡破坏。'),
(10804018, 'Saffira, Divine Dragon of the Voiceless Voice', '肃声龙神 萨菲拉', '粛声なる竜神サフィラ', 'Ritual Effect Monster', 'Dragon', 'LIGHT', 7, 2550, 2450, '「肃声之祝福」降临 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡仪式召唤的场合，若自己的场上或墓地有「肃声的祈祷者 理」存在则能发动。自己抽2张。那之后，选自己1张手卡丢弃。 ②：战士族·龙族而光属性的仪式怪兽进行战斗的攻击宣言时才能发动。对方手卡随机1张丢弃。 ③：对方结束阶段才能发动。从自己墓地把1只光属性怪兽加入手卡。'),
(51296484, 'Saffira, Dragon Queen of the Voiceless Voice', '肃声之龙贤姬 萨菲拉', '粛声の竜賢姫サフィラ', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2500, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张仪式魔法卡送去墓地。那之后，可以把1只战士族·龙族而光属性的仪式怪兽从自己的卡组·墓地加入手卡。 ②：把墓地的这张卡除外才能发动。等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从手卡把1只战士族·龙族而光属性的仪式怪兽仪式召唤。'),
(56350972, 'Saffira, Queen of Dragons', '龙姬神 萨菲拉', '竜姫神サフィラ', 'Ritual Effect Monster', 'Dragon', 'LIGHT', 6, 2500, 2400, '「祝祷的圣歌」降临。这个卡名的效果1回合只能使用1次。 ①：这张卡仪式召唤的回合的结束阶段以及这张卡在怪兽区域存在并从手卡·卡组有光属性怪兽被送去墓地的回合的结束阶段，可以从以下效果选择1个发动。 ●自己从卡组抽2张，那之后选1张手卡丢弃。 ●对方手卡随机选1张丢弃去墓地。 ●选自己墓地1只光属性怪兽加入手卡。'),
(66156348, 'Saga of the Dragon Emperor', '龙皇神话', '竜皇神話', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只龙族怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成2倍。对方场上有龙族怪兽存在的场合，再在这个回合让作为对象的怪兽的效果的发动不会被无效化。 ②：自己主要阶段把墓地的这张卡除外才能发动。从自己墓地的怪兽以及除外的自己怪兽之中选1只龙族超量怪兽守备表示特殊召唤。'),
(34456146, 'Sage of Benevolence - Ciela', '慈爱之贤者－谢拉', '慈愛の賢者－シエラ', 'Effect Monster', 'Machine', 'WATER', 6, 2200, 1000, '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①②③的效果1回合各能使用1次。 ①：从手卡丢弃1张魔法卡才能发动。这张卡从手卡特殊召唤。 ②：从自己墓地把1张魔法卡除外才能发动。这张卡的控制权移给对方，从自己墓地选1只「闪刀姬」怪兽特殊召唤。 ③：这张卡被战斗·效果破坏送去墓地的场合，以除外的1张自己的「闪刀」魔法卡为对象才能发动。那张卡加入手卡。'),
(26669055, 'Sage of Silence', '静寂之圣者', '静寂の聖者', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1400, 1000, '这张卡战斗破坏对方怪兽的场合，对方玩家在下个回合不能发动魔法卡。'),
(62054060, 'Sage of Stillness', '平稳之贤者', '平穏の賢者', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1400, 1000, '这张卡战斗破坏对方怪兽的场合，对方玩家在下个回合不能发动陷阱卡。'),
(96795312, 'Sage of Strength - Akash', '武之贤者－阿卡丝', '武の賢者－アーカス', 'Effect Monster', 'Machine', 'FIRE', 5, 2400, 200, '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①②③的效果1回合各能使用1次。 ①：从手卡丢弃1张魔法卡才能发动。这张卡从手卡特殊召唤。 ②：自己场上的连接怪兽被战斗·效果破坏的场合，可以作为代替把自己墓地1张魔法卡除外。 ③：这张卡被战斗·效果破坏送去墓地的场合，以除外的1张自己的「闪刀」魔法卡为对象才能发动。那张卡加入手卡。'),
(22790910, 'Sage of Wisdom - Himmel', '智之贤者－辛梅尔', '智の賢者－ヒンメル', 'Effect Monster', 'Machine', 'EARTH', 5, 500, 2500, '这个卡名在规则上也当作「闪刀」卡使用。这个卡名的①②③的效果1回合各能使用1次。 ①：从手卡丢弃1张魔法卡才能发动。这张卡从手卡特殊召唤。 ②：自己场上的连接怪兽为对象的效果由对方发动时，从自己墓地把2张魔法卡除外才能发动。那个效果无效。 ③：这张卡被战斗·效果破坏送去墓地的场合，以除外的1张自己的「闪刀」魔法卡为对象才能发动。那张卡加入手卡。'),
(8240199, 'Sage with Eyes of Blue', '青之眼贤士', '青き眼の賢士', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, NULL, 1500, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤时才能发动。从卡组把「青色眼睛的贤士」以外的1只光属性·1星调整加入手卡。 ②：把这张卡从手卡丢弃，以自己场上1只效果怪兽为对象才能发动。那只怪兽送去墓地，从卡组把1只「青眼」怪兽特殊召唤。'),
(13604200, 'Sage''s Stone', '贤者的宝石', '賢者の宝石', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「黑魔术少女」存在的场合才能发动。从手卡·卡组把1只「黑魔术师」特殊召唤。'),
(66602787, 'Saggi the Dark Clown', '暗道化师 扎奇', '闇・道化師のサギー', 'Normal Monster', 'Spellcaster', 'DARK', 3, 600, 1500, '不知从哪里出现的道化师。用不可思议的动作来躲开攻击。'),
(93738004, 'Sagitta, Maverick Fur Hire', '空牙团的孤高 萨吉塔', '空牙団の孤高 サジータ', 'Effect Monster', 'Winged Beast', 'WIND', 5, 1200, 2400, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。给与对方为「空牙团的孤高 莎吉塔」以外的自己场上的「空牙团」怪兽种类×500伤害。 ②：只要这张卡在怪兽区域存在，对方不能把这张卡以外的自己场上的「空牙团」怪兽作为效果的对象。'),
(36608728, 'Saiba the Fighting Swordsmith', '战刀匠 再刃', '戦刀匠サイバ', 'Synchro Monster', 'Warrior', 'EARTH', 7, 2000, 1500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只6星以下的战士族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这张卡在这个回合不能作为同调素材。 ②：对方主要阶段才能发动。用包含战士族怪兽的自己场上的怪兽为素材进行同调召唤。'),
(85065943, 'Saint Azamina', '圣徒蓟主', '聖アザミナ', 'Fusion Monster', 'Illusion', 'DARK', 10, NULL, 4000, '6星以上的融合怪兽＋6星以上的同调怪兽 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，对方不能把这张卡以及对方的场上·墓地·除外状态的卡作为效果的对象，自己受到的战斗伤害由对方代受。 ②：这张卡融合召唤的自己·对方回合才能发动。从卡组·额外卡组把1只9星以下的「蓟花」怪兽特殊召唤。'),
(15130912, 'Saion the Vaylantz Archer', '弈勇之射手－西园', 'ヴァリアンツの弓引－西園', 'Pendulum Effect Monster', 'Spellcaster', 'WATER', 4, 1100, 1100, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡是已特殊召唤的场合，以场上1只效果怪兽为对象才能发动。进行1次投掷硬币。表的场合，那只怪兽的效果无效。里的场合，那个攻击力变成一半。 ②：怪兽区域的这张卡向其他的怪兽区域移动的场合，以场上1张卡为对象才能发动。进行1次投掷硬币。表的场合，那张卡破坏。里的场合，那张卡回到持有者手卡。'),
(67972302, 'Sakitama', '幸魂', '幸魂', 'Spirit Monster', 'Fairy', 'LIGHT', 4, 400, 900, '这张卡不能特殊召唤。这个卡名的①③的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。进行手卡1只灵魂怪兽的召唤。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到手卡。 ③：这张卡被解放的场合，以自己墓地1只灵魂怪兽为对象发动。那只怪兽加入手卡。'),
(47060528, 'Sakra Vendirage', '雷霆之魔军神 帝释天温谛达', '雷霆ノ魔軍神', 'XYZ Monster', 'Psychic', 'DARK', 4, 2000, 2500, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，以「雷霆之魔军神」以外的自己墓地1只4星或4阶的念动力族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：这张卡在怪兽区域存在的状态，怪兽特殊召唤的场合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽的卡名直到结束阶段当作「雷霆之魔军神」使用。'),
(56120475, 'Sakuretsu Armor', '炸裂装甲', '炸裂装甲', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时，以1只攻击怪兽为对象才能发动。那只攻击怪兽破坏。'),
(32268901, 'Salamandra', '飞龙炎', 'サラマンドラ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '炎属性怪兽才能装备。 ①：装备怪兽的攻击力上升700。'),
(9102835, 'Salamandra Fusion', '沙罗曼龙结合', 'サラマンドラ・フュージョン', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '战士族·炎属性怪兽才能装备。这个卡名的③的效果1回合只能使用1次。 ①：装备怪兽的攻击力上升700。 ②：装备怪兽被战斗·效果破坏的场合，可以作为代替把这张卡破坏。 ③：这张卡给自己场上的融合怪兽装备中的场合才能发动。装备怪兽和这张卡送去墓地，把1只「炎之剑士」或者有那个卡名记述的融合怪兽当作融合召唤从额外卡组特殊召唤。'),
(62091148, 'Salamandra with Chain', '带锁链的沙罗曼龙炎刃', '鎖付き飛龍炎刃', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以场上1只炎属性怪兽为对象才能把这张卡发动。这张卡当作攻击力上升700的装备卡使用给那只怪兽装备。那之后，可以把场上1只效果怪兽变成里侧守备表示。 ②：把墓地的这张卡除外才能发动。自己的手卡·场上·墓地的怪兽作为融合素材回到卡组，把1只战士族·龙族而炎属性的融合怪兽融合召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(37531679, 'Salamandra, the Flying Flame Dragon', '飞龙炎 沙罗曼龙', '飛龍炎サラマンドラ', 'Effect Monster', 'Dragon', 'FIRE', 2, 700, 1600, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在的场合，以自己场上1只战士族怪兽为对象才能发动。这张卡当作装备魔法卡使用给那只自己怪兽装备。 ②：只要这张卡给「炎之剑士」或者有那个卡名记述的怪兽装备中，装备怪兽的攻击力上升700。 ③：这张卡被送去墓地的场合才能发动。从卡组把1张「飞龙炎」魔法·陷阱卡加入手卡。'),
(60303245, 'Salamangreat Almiraj', '转生炎兽独角兔', '転生炎獣アルミラージ', 'Link Monster', 'Cyberse', 'FIRE', NULL, NULL, NULL, '通常召唤的攻击力1000以下的怪兽1只 这个卡名的②的效果1回合只能使用1次。 ①：自己·对方回合，把这张卡解放，以自己场上1只怪兽为对象才能发动。这个回合，那只怪兽不会被对方的效果破坏。 ②：这张卡在墓地存在的状态，通常召唤的自己怪兽被战斗破坏时才能发动。这张卡特殊召唤。'),
(14812471, 'Salamangreat Balelynx', '转生炎兽 烽火猞猁', '転生炎獣ベイルリンクス', 'Link Monster', 'Cyberse', 'FIRE', NULL, 500, NULL, '4星以下的电子界族怪兽1只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1张「转生炎兽的圣域」加入手卡。 ②：自己场上的「转生炎兽」卡被战斗·效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(25166510, 'Salamangreat Beat Bison', '转生炎兽 B野牛', '転生炎獣Bバイソン', 'Effect Monster', 'Cyberse', 'FIRE', 8, 2800, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己墓地有「转生炎兽」怪兽3只以上存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：以最多有对方场上的表侧表示的卡数量的自己墓地的炎属性连接怪兽为对象才能发动。那些怪兽回到额外卡组。那之后，可以选最多有回去的卡数量的对方场上的表侧表示的卡，直到回合结束时那个效果无效。'),
(9608555, 'Salamangreat Blaze Dragon', '转生炎兽 烈火龙', '転生炎獣ブレイズ・ドラゴン', 'XYZ Monster', 'Cyberse', 'FIRE', 4, 2300, 1200, '4星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：这张卡被战斗·效果破坏的场合，作为代替把这张卡1个超量素材取除。 ②：这张卡没有超量素材的场合，自己·对方的战斗阶段才能发动。把1只「转生炎兽」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。 ③：这张卡用「转生炎兽 烈焰龙」为素材作超量召唤成功的场合才能发动。选对方场上1只怪兽破坏。'),
(28534130, 'Salamangreat Burning Shell', '转生炎兽之炎虞', '転生炎獣の炎虞', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡把1只「转生炎兽」怪兽效果无效特殊召唤，用包含那只怪兽的自己场上的怪兽为素材把1只「转生炎兽」连接怪兽连接召唤。这个回合，这个效果连接召唤的怪兽不能攻击，不能把效果发动。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地1只「转生炎兽」连接怪兽为对象才能发动。那只怪兽回到额外卡组。'),
(10140443, 'Salamangreat Burst Gryphon', '转生炎兽 爆裂狮鹫', '転生炎獣バースト・グリフォン', 'Synchro Monster', 'Cyberse', 'FIRE', 8, 2800, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只7星以下的炎属性怪兽为对象才能发动。那只怪兽特殊召唤，这张卡的等级下降那只怪兽的原本等级数值。这个回合，自己不是炎属性怪兽不能特殊召唤。 ②：这张卡用「转生炎兽 爆裂狮鹫」为素材作同调召唤的场合才能发动。下次的准备阶段从自己墓地把1只怪兽特殊召唤。'),
(83533296, 'Salamangreat Charge', '转生炎兽之炎军', '転生炎獣の炎軍', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●以自己的墓地·除外状态的3只炎属性怪兽为对象才能发动。那3只之内的2只回到卡组，剩下的1只特殊召唤。这个效果特殊召唤的怪兽在这个回合效果无效化，不能攻击。 ●持有和原本攻击力不同攻击力的炎属性的仪式·融合·同调·超量·连接怪兽在自己场上存在的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(52155219, 'Salamangreat Circle', '转生炎兽之炎阵', '転生炎獣の炎陣', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从卡组把1只「转生炎兽」怪兽加入手卡。 ●以用和自身同名的怪兽为素材作连接召唤的自己场上1只「转生炎兽」连接怪兽为对象才能发动。这个回合，那只连接怪兽不受自身以外的怪兽的效果影响。'),
(88540324, 'Salamangreat Claw', '转生炎兽之烈爪', '転生炎獣の烈爪', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「转生炎兽」怪兽才能装备。 ①：「转生炎兽的烈爪」在自己场上只能有1张表侧表示存在。 ②：装备怪兽不会被战斗·效果破坏，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：装备怪兽是用和自身同名的怪兽为素材作连接召唤的自己的「转生炎兽」连接怪兽的场合，装备怪兽在同1次的战斗阶段中可以向怪兽作出最多有那个连接标记数量的攻击。'),
(71861848, 'Salamangreat Coyote', '转生炎兽 草原狼', '転生炎獣コヨーテ', 'Effect Monster', 'Cyberse', 'FIRE', 3, 1000, 200, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为连接素材送去墓地的回合的结束阶段可以从以下效果选择1个发动。 ●以「转生炎兽 郊狼」以外的自己墓地1只「转生炎兽」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ●以「转生炎兽 郊狼」以外的自己墓地1张「转生炎兽」卡为对象才能发动。那张卡加入手卡。'),
(16313112, 'Salamangreat Emerald Eagle', '转生炎兽 翡翠鹰', '転生炎獣エメラルド・イーグル', 'Ritual Effect Monster', 'Cyberse', 'FIRE', 8, 2800, 2000, '「转生炎兽的降临」降临。 ①：这张卡使用自己场上的「转生炎兽 翠玉鹰」作仪式召唤成功时才能发动。对方场上的特殊召唤的怪兽全部破坏。 ②：1回合1次，把自己场上1只「转生炎兽」连接怪兽解放才能发动。这个回合，这张卡得到以下效果。 ●这张卡和对方怪兽进行战斗的伤害步骤开始时发动。那只对方怪兽破坏，给与对方那个原本攻击力数值的伤害。'),
(20618081, 'Salamangreat Falco', '转生炎兽 列鹰', '転生炎獣ファルコ', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1200, 1600, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡被送去墓地的场合，以自己墓地1张「转生炎兽」魔法·陷阱卡为对象才能发动。那张卡在自己场上盖放。 ②：这张卡在墓地存在的场合，以「转生炎兽 猎鹰」以外的自己场上1只「转生炎兽」怪兽为对象才能发动。那只怪兽回到持有者手卡，这张卡从墓地特殊召唤。'),
(49094491, 'Salamangreat Fennec', '转生炎兽 大耳狐', '転生炎獣フェネック', 'Effect Monster', 'Cyberse', 'FIRE', 3, 1600, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，从额外卡组特殊召唤的自己场上的电子界族怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡作为连接2以上的电子界族连接怪兽的连接素材送去墓地的场合才能发动。从卡组把1张「转生炎兽」通常魔法卡加入手卡。'),
(89662401, 'Salamangreat Fowl', '转生炎兽 雄孔雀', '転生炎獣フォウル', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1800, 200, '这个卡名的①的效果1回合只能使用1次。 ①：自己场上有「转生炎兽 孔雀」以外的「转生炎兽」怪兽召唤·特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：从手卡以及自己场上的表侧表示的卡之中把1张「转生炎兽」卡送去墓地，以对方场上盖放的1张魔法·陷阱卡为对象才能发动。这个回合，那张盖放的魔法·陷阱卡不能发动。'),
(86962245, 'Salamangreat Foxer', '转生炎兽 狐飒', '転生炎獣フォクサー', 'Effect Monster', 'Cyberse', 'FIRE', 3, 1200, 1000, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己墓地的「转生炎兽」怪兽是3只以上的场合，把这张卡从手卡送去墓地，以自己墓地1只「转生炎兽」连接怪兽和对方的魔法与陷阱区域1张卡为对象才能发动。作为对象的墓地的怪兽回到额外卡组，作为对象的场上的卡破坏。 ②：这张卡在墓地存在，对方的魔法与陷阱区域的卡被破坏送去墓地的场合才能发动。这张卡守备表示特殊召唤。'),
(94620082, 'Salamangreat Foxy', '转生炎兽 狐曦', '転生炎獣フォクシー', 'Effect Monster', 'Cyberse', 'FIRE', 3, 1000, 1200, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤成功时才能发动。从自己卡组上面把3张卡翻开。可以从那之中选1张「转生炎兽」卡加入手卡。剩下的卡回到卡组。 ②：这张卡在墓地存在，场上有表侧表示的魔法·陷阱卡存在的场合，从手卡丢弃1张「转生炎兽」卡才能发动。这张卡特殊召唤。那之后，可以选场上1张表侧表示的魔法·陷阱卡破坏。'),
(26889158, 'Salamangreat Gazelle', '转生炎兽 羚羊', '転生炎獣ガゼル', 'Effect Monster', 'Cyberse', 'FIRE', 3, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：「转生炎兽 羚羊」以外的「转生炎兽」怪兽被送去自己墓地的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「转生炎兽 羚羊」以外的1张「转生炎兽」卡送去墓地。'),
(20788863, 'Salamangreat Gift', '转生炎兽的赠礼', 'サラマングレイト・ギフト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从手卡丢弃1只「转生炎兽」怪兽才能发动。从卡组把1只「转生炎兽」怪兽送去墓地。那之后，自己从卡组抽1张。 ②：用和自身同名的怪兽为素材作连接召唤的「转生炎兽」连接怪兽在自己场上存在的场合，从手卡丢弃1只「转生炎兽」怪兽才能发动。自己从卡组抽2张。'),
(41463181, 'Salamangreat Heatleo', '转生炎兽 炽热猛狮', '転生炎獣ヒートライオ', 'Link Monster', 'Cyberse', 'FIRE', NULL, 2300, NULL, '炎属性效果怪兽2只以上 ①：这张卡连接召唤的场合，以对方的魔法与陷阱区域1张卡为对象才能发动。那张卡回到卡组。 ②：这张卡是已用「转生炎兽 炽热多头狮」为素材作连接召唤的场合，1回合1次，以场上1只表侧表示怪兽和自己墓地1只怪兽为对象才能发动。作为对象的场上的怪兽的攻击力直到回合结束时变成和作为对象的墓地的怪兽的攻击力相同。'),
(56003780, 'Salamangreat Jack Jaguar', '转生炎兽 J美洲豹', '転生炎獣Jジャガー', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1800, 1200, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：这张卡在墓地存在，自己场上有「转生炎兽」连接怪兽存在的场合，以「转生炎兽 灯火美洲豹」以外的自己墓地1只「转生炎兽」怪兽为对象才能发动。那只怪兽回到卡组，墓地的这张卡在作为自己的「转生炎兽」连接怪兽所连接区的自己场上特殊召唤。'),
(67225377, 'Salamangreat Meer', '转生炎兽 狐猛', '転生炎獣ミーア', 'Effect Monster', 'Cyberse', 'FIRE', 2, 800, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用通常抽卡以外的方法加入手卡的场合，把这张卡给对方观看才能发动。这张卡从手卡特殊召唤。 ②：从手卡把这张卡以外的1张「转生炎兽」卡丢弃才能发动。这张卡从手卡特殊召唤。'),
(87327776, 'Salamangreat Miragestallio', '转生炎兽 幻象雄马', '転生炎獣ミラージュスタリオ', 'XYZ Monster', 'Cyberse', 'FIRE', 3, 2000, 900, '3星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组把1只「转生炎兽」怪兽守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不能把炎属性以外的怪兽的效果发动。 ②：超量召唤的这张卡作为「转生炎兽」连接怪兽的连接素材送去墓地的场合，以场上1只怪兽为对象才能发动。那只怪兽回到手卡。'),
(89484053, 'Salamangreat Mole', '转生炎兽 鼹', '転生炎獣モル', 'Effect Monster', 'Cyberse', 'FIRE', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己对连接怪兽的连接召唤成功的回合的自己主要阶段才能发动。手卡的这张卡在作为连接怪兽所连接区的自己场上特殊召唤。 ②：自己场上没有怪兽存在的场合，把墓地的这张卡除外，以自己墓地5张「转生炎兽」卡为对象才能发动。那些卡加入卡组洗切。那之后，自己从卡组抽2张。'),
(11962031, 'Salamangreat of Fire', '火焰转生炎兽', 'サラマングレイト・オブ・ファイア', 'Effect Monster', 'Cyberse', 'FIRE', 2, 800, 800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。除「炽焰转生炎兽小妖」外的1只4星以下的「转生炎兽」怪兽从卡组加入手卡。这个效果的发动后，直到回合结束时自己不是炎属性怪兽不能特殊召唤。 ②：自己的电子界族怪兽进行战斗的伤害步骤开始时，把墓地的这张卡除外才能发动。那只自己怪兽破坏。'),
(59577547, 'Salamangreat Parro', '转生炎兽 鹦武', '転生炎獣パロー', 'Effect Monster', 'Cyberse', 'FIRE', 5, 2000, 1000, '这个卡名的③的效果1回合只能使用1次。 ①：对方怪兽的攻击宣言时才能发动。这张卡从手卡攻击表示特殊召唤。 ②：这张卡特殊召唤成功的场合，以自己墓地1只「转生炎兽」怪兽为对象才能发动。这张卡的攻击力变成和那只怪兽的攻击力相同。 ③：把这张卡解放才能发动。自己回复2000基本分。'),
(31313405, 'Salamangreat Pyro Phoenix', '转生炎兽 浴火不死鸟', '転生炎獣パイロ・フェニックス', 'Link Monster', 'Cyberse', 'FIRE', NULL, 2800, NULL, '炎属性效果怪兽2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡用「转生炎兽 火凤凰」为素材作连接召唤成功的场合才能发动。对方场上的卡全部破坏。 ②：以对方墓地1只连接怪兽为对象才能发动。那只怪兽在对方场上特殊召唤。 ③：对方场上有连接怪兽特殊召唤的场合，以那1只怪兽为对象才能发动。给与对方那只怪兽的原本攻击力数值的伤害。'),
(53490455, 'Salamangreat Raccoon', '转生炎兽 貉', '転生炎獣ラクーン', 'Effect Monster', 'Cyberse', 'FIRE', 1, 400, 800, '这个卡名的②的效果1回合只能使用1次。 ①：自己的「转生炎兽」怪兽被选择作为对方怪兽的攻击对象时，把这张卡从手卡送去墓地，以那2只进行战斗的怪兽为对象才能发动。自己基本分回复作为对象的对方怪兽的攻击力的数值。这个回合，作为对象的自己怪兽不会被战斗破坏。 ②：这张卡在墓地存在，自己的「转生炎兽」怪兽战斗破坏对方怪兽送去墓地时才能发动。这张卡加入手卡。'),
(14934922, 'Salamangreat Rage', '转生炎兽的愤怒', 'サラマングレイト・レイジ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●从手卡以及自己场上的表侧表示怪兽之中把1只「转生炎兽」怪兽送去墓地，以场上1张卡为对象才能发动。那张卡破坏。 ●以用和自身同名的怪兽为素材作连接召唤的自己场上1只「转生炎兽」连接怪兽为对象才能发动。选最多有那只怪兽的连接标记数量的对方场上的卡破坏。'),
(57134592, 'Salamangreat Raging Phoenix', '转生炎兽 怒火不死鸟', '転生炎獣レイジング・フェニックス', 'Link Monster', 'Cyberse', 'FIRE', NULL, 2800, NULL, '炎属性效果怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡用「转生炎兽 烈火凤凰」为素材作连接召唤的场合才能发动。从卡组把1张「转生炎兽」卡加入手卡。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的炎属性怪兽被战斗·效果破坏的场合，以那之内的1只为对象才能发动。这张卡特殊召唤，这张卡的攻击力上升作为对象的怪兽的攻击力数值。'),
(83554231, 'Salamangreat Recureance', '转生炎兽之再起', '転生炎獣の再起', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地2只卡名不同的「转生炎兽」怪兽为对象才能发动。那些怪兽加入手卡。 ②：盖放的这张卡被效果破坏送去墓地的场合才能发动。从卡组把「转生炎兽的再起」以外的1张「转生炎兽」魔法·陷阱卡加入手卡。'),
(19027895, 'Salamangreat Revive', '转生炎兽的复生', 'サラマングレイト・リヴァイブ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地1只炎属性怪兽为对象才能发动。那只怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己场上1只「转生炎兽」怪兽和自己墓地1只同名怪兽为对象才能发动。那只墓地的怪兽回到卡组，那只自己场上的怪兽的攻击力直到回合结束时上升自身的原本攻击力数值。'),
(51339637, 'Salamangreat Roar', '转生炎兽的咆哮', 'サラマングレイト・ロアー', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「转生炎兽」连接怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：这张卡在墓地存在的状态，和自身同名的怪兽作为素材让「转生炎兽」连接怪兽在自己场上连接召唤的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(1295111, 'Salamangreat Sanctuary', '转生炎兽之圣域', '転生炎獣の聖域', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：只要这张卡在场地区域存在，自己要把「转生炎兽」连接怪兽连接召唤的场合，可以只用自己场上1只同名「转生炎兽」连接怪兽为素材作连接召唤。 ②：自己怪兽进行战斗的伤害计算时，支付1000基本分，以自己场上1只连接怪兽为对象才能发动。那只怪兽的攻击力变成0，自己基本分回复那只怪兽的原本攻击力的数值。'),
(52277807, 'Salamangreat Spinny', '转生炎兽 刺尾蜥', '転生炎獣スピニー', 'Effect Monster', 'Cyberse', 'FIRE', 3, 1000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「转生炎兽」卡存在的场合，把这张卡从手卡丢弃，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升500。 ②：自己场上有「转生炎兽 犰狳蜥」以外的「转生炎兽」怪兽存在的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(87871125, 'Salamangreat Sunlight Wolf', '转生炎兽 日光狼', '転生炎獣サンライトウルフ', 'Link Monster', 'Cyberse', 'FIRE', NULL, 1800, NULL, '炎属性效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡所连接区有怪兽召唤·特殊召唤的场合才能发动。从自己墓地把1只炎属性怪兽加入手卡。这个回合，自己不能把这个效果加入手卡的怪兽以及那些同名怪兽通常召唤·特殊召唤。 ②：这张卡是已用「转生炎兽 日光狼」为素材作连接召唤的场合才能发动。从自己墓地把1张「转生炎兽」魔法·陷阱卡加入手卡。'),
(84755744, 'Salamangreat Tiger', '转生炎兽 老虎', '転生炎獣ティガー', 'Tuner Monster', 'Cyberse', 'FIRE', 5, 2000, 500, '这个卡名的①的效果1回合只能使用1次。 ①：从手卡丢弃1张其他的「转生炎兽」卡才能发动。这张卡从手卡特殊召唤。 ②：把自己场上的这张卡作为炎属性同调怪兽的同调素材的场合，可以把这张卡当作调整以外的怪兽使用。 ③：1回合1次，自己主要阶段才能发动。这张卡的等级上升或下降1星。'),
(54529134, 'Salamangreat Transcendence', '转生炎兽之超转生', '転生炎獣の超転生', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「转生炎兽」连接怪兽为对象才能发动。只用那1只自己怪兽为素材把1只同名「转生炎兽」连接怪兽当作连接召唤从额外卡组特殊召唤。'),
(37261776, 'Salamangreat Violet Chimera', '转生炎兽 堇色客迈拉', '転生炎獣ヴァイオレットキマイラ', 'Fusion Monster', 'Cyberse', 'FIRE', 8, 2800, 2000, '「转生炎兽」怪兽＋连接怪兽 ①：这张卡融合召唤的场合才能发动。这张卡的攻击力直到回合结束时上升作为这张卡的融合素材的怪兽的原本攻击力合计数值的一半。 ②：这张卡和持有和原本攻击力不同攻击力的怪兽进行战斗的伤害计算时才能发动1次。这张卡的攻击力只在那次伤害计算时变成2倍。 ③：和用「转生炎兽 堇色奇美拉」为素材作融合召唤的这张卡进行战斗的怪兽的攻击力只在伤害计算时变成0。'),
(57357130, 'Salamangreat Weasel', '转生炎兽 黄鼠狼', '転生炎獣ウィーゼル', 'Tuner Monster', 'Cyberse', 'FIRE', 3, 700, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己墓地的「转生炎兽」怪兽是2只以上的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡在墓地存在的状态，自己场上有「转生炎兽」仪式·融合·同调·超量·连接怪兽特殊召唤的场合，以这张卡以外的自己墓地1只「转生炎兽」怪兽为对象才能发动。这张卡回到卡组最下面，作为对象的怪兽在对方场上特殊召唤。那之后，自己抽1张。'),
(13173832, 'Salamangreat Wolvie', '转生炎兽 獾狼', '転生炎獣ウルヴィー', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1700, 1000, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：这张卡为素材作连接召唤成功的怪兽在那个回合不会被战斗·效果破坏。 ②：这张卡从墓地的特殊召唤成功的场合，以自己墓地1只炎属性怪兽为对象才能发动。那只怪兽加入手卡。 ③：这张卡因效果从自己墓地加入手卡的场合，把这张卡给对方观看，以自己墓地1只炎属性怪兽为对象才能发动。那只怪兽加入手卡。'),
(44161893, 'Salamangreat Zebroid X', '转生炎兽 类斑马X', '転生炎獣ゼブロイドX', 'Effect Monster', 'Cyberse', 'FIRE', 4, 1500, 100, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在墓地存在，自己的「转生炎兽」连接怪兽因对方的效果从场上离开的场合才能发动。从自己墓地选包含这张卡的2只4星「转生炎兽」怪兽效果无效特殊召唤，只用那2只为素材把1只「转生炎兽」怪兽超量召唤。 ②：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这张卡的攻击力上升这张卡的超量素材数量×300。'),
(64964750, 'Sales Ban', '禁售令', '発禁令', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：宣言1个卡名才能发动。这个回合，对方不能把原本卡名和宣言的卡相同的卡的效果发动。这次决斗中，自己不能把原本卡名和宣言的卡相同的卡的效果发动。'),
(2971446, 'Sales Pitch', '复制品兜销', 'キャッチ・コピー', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：对方的效果让对方用抽卡以外的方法从卡组把卡加入手卡的场合才能发动。自己从卡组选1张卡，给双方确认加入手卡。这个回合，自己不能作这个效果加入手卡的卡以及那些同名卡的效果的发动。'),
(96947648, 'Salvage', '打捞', 'サルベージ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地2只攻击力1500以下的水属性怪兽为对象才能发动。那些水属性怪兽加入手卡。'),
(41705642, 'Salvage Warrior', '打捞战士', 'サルベージ・ウォリアー', 'Effect Monster', 'Warrior', 'WATER', 5, 1900, 1600, '这张卡上级召唤成功时，可以从手卡或者自己墓地把1只调整特殊召唤。'),
(62306203, 'Salvagent Driver', '抢救代理驱动者', 'サルベージェント・ドライバー', 'Effect Monster', 'Cyberse', 'LIGHT', 6, 2200, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上的电子界族连接怪兽被对方的效果破坏的场合才能发动。这张卡特殊召唤。 ②：从手卡丢弃1张魔法卡，以自己墓地1只电子界族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能直接攻击。'),
(44182827, 'Samsara', '轮回转生', '輪廻転生', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '作为仪式召唤的祭品的怪兽卡不去墓地，回到持有者的卡组。之后卡组洗切。'),
(62318994, 'Samsara D Lotus', '纳祭魔鬼莲', 'サクリファイス・D・ロータス', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：把这张卡解放才能发动。从卡组把1只「于贝尔」怪兽特殊召唤。 ②：对方回合，自己场上有「于贝尔」怪兽存在，怪兽的效果发动时，把这张卡解放才能发动。那个效果变成「场上1只「于贝尔」怪兽破坏」。 ③：这张卡在墓地存在，自己场上有「于贝尔」存在的场合，自己结束阶段才能发动。这张卡加入手卡或特殊召唤。');